// Generated by vibelang from src/runtime/plugin/panel-keys.ts; the migrate flow writes it again with each batch.
/** The key the host stores a panel tab under. */
export function panelKey(plugin, id) {
    return `${plugin}:${id}`;
}
/** The stored keys the panels map with `BuiltinPanel.legacy`, each to the key of the tab it is now. */
export function legacyKeys(providers) {
    return new Map(providers.flatMap((item) => Object.entries(item.value.legacy ?? {}).map(([key, id]) => [key, panelKey(item.plugin, id)])));
}
